std::map<int,uiMotion::Toggle> switchMotions;
bool switchesMoving=false;LONGLONG switchesLastTick=0;
inline float switchPosition(int id,bool on){
    auto&motion=switchMotions[id];motion.set(on,!selfTestMode&&!reducedMotion()&&IsWindowVisible(mainWindow)&&!IsIconic(mainWindow));
    if(motion.moving()&&!switchesMoving){switchesLastTick=motionNow();switchesMoving=startUiAnimationTimer(mainWindow,76)!=0;if(!switchesMoving)motion.set(on,false);}
    return motion.position;
}
inline void tickSwitches(){
    auto now=motionNow();float elapsed=float((now-switchesLastTick)/motionFrequency());switchesLastTick=now;
    bool animate=!reducedMotion()&&IsWindowVisible(mainWindow)&&!IsIconic(mainWindow),moving=false;
    auto const&visibleHits=hits();for(auto&entry:switchMotions){bool visible=false;for(auto&hit:visibleHits)visible=visible||hit.id==entry.first;
        if(!animate||!visible)entry.second.set(entry.second.target!=0,false);
        else moving=entry.second.tick(elapsed)||moving;
    }
    switchesMoving=moving;if(!moving)stopUiAnimationTimer(mainWindow,76);InvalidateRect(mainWindow,nullptr,FALSE);
}
struct SegmentMotion {float fromX=252,toX=252,fromWidth=98,toWidth=98;double start=0;int destination=-1;bool moving=false;};
SegmentMotion segmentMotions[2];
inline Renderer&renderer(); // defined after this header
// Design widths fit the Chinese labels; a longer translation widens its segment/button/line instead of overflowing.
inline const wchar_t*segName(bool settings,int i){return i==2?L"LGEngine":settings?(i?tr(L"关于",L"About"):tr(L"常规",L"General")):(i?tr(L"材质调节",L"Materials"):tr(L"效果开关",L"Effects"));}
inline float segWidth(bool settings,int i,bool selected){float design=settings?72.f:i==2?(selected?107.f:104.f):98.f,need=std::ceil(renderer().textWidth(segName(settings,i),12,true)+20);return need<=design?design:need;}
inline float segX(bool settings,int i){float x=252;for(int k=0;k<i;++k)x+=segWidth(settings,k,false)+4;return x;}
inline float segRight(bool settings,int selected){int last=settings?1:2;return segX(settings,last)+segWidth(settings,last,selected==last)+4;}
inline float buttonFit(const wchar_t*text,float design){float need=renderer().textWidth(text,13)+47;return need<=design?design:std::ceil(need+8);}
inline D2D1_RECT_F optButtonRect(bool sampleButton){float replay=buttonFit(tr(L"重播",L"Replay"),78),indicator=buttonFit(tr(L"示例指示器",L"Sample indicator"),114);return sampleButton?D2D1_RECT_F{272+replay+12,430,272+replay+12+indicator,468}:D2D1_RECT_F{272,430,272+replay,468};}
// DirectWrite trimming is skipped for line-spaced and optically centred labels, so shorten the text ourselves.
inline std::wstring fitText(const std::wstring&s,float size,float maxWidth){
    static std::map<std::tuple<std::wstring,float,float>,std::wstring> cache;auto key=std::make_tuple(s,size,maxWidth);auto found=cache.find(key);if(found!=cache.end())return found->second;
    auto&r=renderer();std::wstring out=s;if(r.textWidth(s,size)>maxWidth){size_t lo=0,hi=s.size();while(lo<hi){size_t mid=(lo+hi+1)/2;if(r.textWidth(s.substr(0,mid)+L"…",size)<=maxWidth)lo=mid;else hi=mid-1;}while(lo>0&&lo<s.size()&&((s[lo]>=0xDC00&&s[lo]<=0xDFFF)||(s[lo]>=0x300&&s[lo]<=0x36F)))--lo;out=s.substr(0,lo)+L"…";}
    if(cache.size()>=64)cache.clear();cache[key]=out;return out;
}
inline std::pair<float,float> segmentAt(const SegmentMotion&s,double now){float t=s.moving?std::clamp(float((now-s.start)/220),0.f,1.f):1.f;float ease=1-std::pow(1-t,3);return {s.fromX+(s.toX-s.fromX)*ease,s.fromWidth+(s.toWidth-s.fromWidth)*ease};}
inline void startSegment(bool settings,int previous,int next){auto&s=segmentMotions[settings?1:0];if(previous==next)return;auto width=[&](int index){return segWidth(settings,index,true);};if(s.destination<0){s.toX=segX(settings,previous);s.toWidth=width(previous);}auto current=segmentAt(s,uiNow());s.fromX=current.first;s.fromWidth=current.second;s.toX=segX(settings,next);s.toWidth=width(next);s.destination=next;s.start=uiNow();s.moving=!legacy&&!selfTestMode&&!reducedMotion()&&IsWindowVisible(mainWindow);if(s.moving&&!startUiAnimationTimer(mainWindow,73))s.moving=false;InvalidateRect(mainWindow,nullptr,FALSE);}
inline void tickSegments(){bool any=false;for(auto&s:segmentMotions){if(s.moving&&(reducedMotion()||!IsWindowVisible(mainWindow)||uiNow()-s.start>=220))s.moving=false;any=any||s.moving;}if(!any)stopUiAnimationTimer(mainWindow,73);InvalidateRect(mainWindow,nullptr,FALSE);}
inline float segmentContentOffset(bool settings){auto&s=segmentMotions[settings?1:0];if(!s.moving)return 0;float t=std::clamp(float((uiNow()-s.start)/220),0.f,1.f);return 8*std::pow(1-t,3);}
